const float intensity = 100.0;
const vec2 shape = vec2(10,10);
const float speed_x = 3.0;
const float speed_y = 3.0;
const vec2 tilt = vec2(-1.0,1.0);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   

    // Some horizontal lines
    float hori_lines = sin(iTime*speed_x+
                            (fragCoord[1]+tilt[0]*fragCoord[0])/shape[0])/(1.0/intensity);

    // some vertical lines
    float verti_lines = sin(iTime*speed_y
                            +(fragCoord[0]+tilt[1]*fragCoord[1])/shape[1])/(1.0/intensity);


    // Output to screen
    // Both set of lines together makes a kind of checker pattern
    fragColor = vec4(0,0,0,1.0) + verti_lines + hori_lines;
}
